Definition sc_frm (ff ioc fp : Z) (h3 : word) (j16 j32 : list byte) : list cell :=
  [C8 (Z_to_bv 64 HZ_MAGIC); C8 (Z_to_bv 64 SC_DESCR); C8 (Z_to_bv 64 P_A_STREAM_CTOR); C8 h3;
   C8 (Z_to_bv 64 ioc); CB 16 j16; C8 (Z_to_bv 64 AT_ANYEX_OBJECT_FNS); C8 (Z_to_bv 64 (ff + 32)); C8 (Z_to_bv 64 AT_ANYEX_TARGET_FNS);
   C8 (Z_to_bv 64 AT_ANYEX_PROP_FNS); CB 32 j32; C8 (Z_to_bv 64 fp)].

(* [comment removed for export] *)
Definition sc_loc (p0 p8 p16 : list byte) (ff : Z) (p32 p40 p48 p56 : list byte) : list cell :=
